import socket
# Let's scan ports on localhost and 192.168.0.2 and any other IPs in 192.168.0.x
for ip in ['127.0.0.1', '192.168.0.1', '192.168.0.2', '192.168.0.3', '192.168.0.5']:
    for port in [80, 443, 8000, 8080, 5000, 3000, 8081, 9000, 53]:
        s = socket.socket()
        s.settimeout(0.05)
        try:
            s.connect((ip, port))
            print(f'{ip}:{port} open')
        except:
            pass
        finally:
            s.close()
